import{z as E,x as p,o as t,c as h,q as o,j as r,D as e,d as i,s,S as d,b as n}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"Count-Min Sketch","description":"","frontmatter":{"title":"Count-Min Sketch","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/count-min-sketch.md","filePath":"cs/count-min-sketch.md","lastUpdated":1791413859000}'),m={name:"cs/count-min-sketch.md"};function c(A,a,u,B,C,f){const l=p("Mermaid");return t(),h("div",null,[a[2]||(a[2]=o('<h1 id="count-min-sketch" tabindex="-1">Count-Min Sketch <a class="header-anchor" href="#count-min-sketch" aria-label="Permalink to &quot;Count-Min Sketch&quot;">​</a></h1><div class="epigraph"><p>若干行哈希表只做加法和取最小；点查询是各行估计的最小，偏高但不偏低（非负流）。</p><footer>—— 据 Cormode and Muthukrishnan, An Improved Data Stream Summary: The Count-Min Sketch and Its Applications, J. Algorithms 2005 整理</footer></div><p><a href="/cs/consistent-hashing">上一课</a> 仍精确放置键。<a href="/cs/universal-hashing">通用散列</a> 给出行间独立。<a href="/cs/bloom-filter">布隆</a> 只回答成员。流上要频次，不能存 \\(n\\) 个计数器。本课不画环。缺口是 Count-Min：宽 \\(w\\)、深 \\(d\\) 的计数矩阵。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>流中元素更新 \\((x,\\Delta)\\)，\\(\\Delta\\ge 0\\)。查询 \\(\\hat{f}(x)=\\min_j \\mathrm{CM}[j,h_j(x)]\\)。真频 \\(f(x)\\le\\hat{f}(x)\\)。取 \\(w=\\lceil e/\\varepsilon\\rceil\\)，\\(d=\\lceil\\ln(1/\\delta)\\rceil\\)，有 \\(\\Pr[\\hat{f}(x)\\gt f(x)+\\varepsilon\\|f\\|_1]\\le\\delta\\)。缺口是<strong>用最小压住其它键的碰撞噪音</strong>，空间 \\(O((1/\\varepsilon)\\log(1/\\delta))\\) 与 \\(n\\) 无关。</p><p><span class="marginnote">Cormode and Muthukrishnan, <em>Journal of Algorithms</em>, 2005。行哈希 pairwise 独立通常够用。</span></p><p><span class="marginnote">数字实例：取 \\(\\varepsilon=0.01\\)、\\(\\delta=0.01\\)，则 \\(w=\\lceil e/\\varepsilon\\rceil\\approx 272\\) 列、\\(d=\\lceil\\ln(1/\\delta)\\rceil=5\\) 行，一共约 1360 个计数器——不管流里是一万个还是一亿个不同元素，空间都是这么多，误差保证也不变，这正是「与 \\(n\\) 无关」的含义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>更新：每行 \\(h_j(x)\\) 槽加 \\(\\Delta\\)。查询取 min。合并：两个同形 sketch 对槽相加，适合分布式。负更新破坏「只偏高」，要 Count-Mean-Min 或换结构，本课钉非负。</p>',9)),(t(),r(d,null,{default:e(()=>[s(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%85%83%E7%B4%A0%20x%22%5D%20--%3E%20ROWS%5B%22d%20%E8%A1%8C%E7%8B%AC%E7%AB%8B%20h_j%22%5D%0A%20%20ROWS%20--%3E%20ADD%5B%22%E5%AF%B9%E5%BA%94%E6%A7%BD%20%2B%3D%20%CE%94%22%5D%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20MIN%5B%22%E5%90%84%E8%A1%8C%E4%BC%B0%E8%AE%A1%E5%8F%96%20min%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("p",null,"与 HyperLogLog：CM 估频次；HLL 估基数。与完美散列：CM 允许错，空间小。",-1)),a[4]||(a[4]=n("h2",{id:"机制",tabindex:"-1"},[i("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=n("p",null,"碰撞只把别人的质量加进来，故高估。min 降低「某一行特别倒霉」的概率。\\(\\|f\\|_1\\) 是流总质量，热键相对误差小、冷键可能被噪音淹没——这是草图边界，不是实现 bug。",-1)),(t(),r(d,null,{default:e(()=>[s(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%9F%A5%E8%AF%A2%20x%20%E7%9C%9F%E5%AE%9E%E9%A2%91%E6%AC%A1%2010%22%5D%20--%3E%20R1%5B%22%E8%A1%8C1%20%E6%A7%BD%E5%80%BC%2010%20%E6%B2%A1%E6%92%9E%E4%B8%8A%22%5D%0A%20%20X%20--%3E%20R2%5B%22%E8%A1%8C2%20%E6%A7%BD%E5%80%BC%2037%20%E6%92%9E%E4%B8%8A%E7%83%AD%E9%94%AE%22%5D%0A%20%20X%20--%3E%20R3%5B%22%E8%A1%8C3%20%E6%A7%BD%E5%80%BC%2012%20%E8%BD%BB%E5%BE%AE%E7%A2%B0%E6%92%9E%22%5D%0A%20%20R1%20--%3E%20MIN%5B%22%E5%8F%96%20min%20%E4%BC%B0%E4%B8%BA%2010%22%5D%0A%20%20R2%20--%3E%20MIN%0A%20%20R3%20--%3E%20MIN%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">这张图回答「min 为什么能压噪音」：碰撞只会把别人的计数加进你的槽，所以每个槽只会偏高；只要有一行没撞或撞得少，取最小就把水分挤掉了。全撞上才会明显高估，而 \\(d\\) 行独立哈希让「全撞」的概率是 \\(\\delta\\)。</span></p><p><span class="marginnote">直觉类比：CM 像 5 个互不通气的朋友各自记账。有人问「我总共付过多少」，你取 5 本账里的最小值——就算某个朋友把你和常客记混了，他记的也只会偏多，最小值天然挤掉混账。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Count-Sketch（中位数、可负）写完。基数估计下一课 HLL。成员过滤器仍布隆/布谷。</p><p>后课默认：非负频次近似用 Count-Min。不同元素个数用 HyperLogLog。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Count-Min：高估频次，空间随 \\(\\varepsilon,\\delta\\)，与 \\(n\\) 无关。</li><li>查询取行 min；适合非负流。</li><li>下一课估基数而非频次。</li><li>出处：Cormode and Muthukrishnan, 2005。</li></ul>',7))])}const k=E(m,[["render",c]]);export{D as __pageData,k as default};
